WITH flattened_attrs AS (SELECT id, plan, currency, tier_limits, discounts, ARRAY_MIN(tier_prices) AS lowest_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT id, currency, lowest_price, entry_price, ROW_NUMBER() OVER (PARTITION BY currency ORDER BY entry_price, id) AS event_seq, SUM(lowest_price) OVER (PARTITION BY plan ORDER BY lowest_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_lowest_price FROM flattened_attrs WHERE currency = 'USD';
